mapper.select:
SELECT id, tool_invocation_id, run_id, request_id, request_source, session_id, tool_call_id, status, error_msg,
       prompt, mode, summary, size, batch_count, source_image_count, mask_image_count, used_fallback, created_at, updated_at
FROM ai_agent_tool_output_image_generation
WHERE request_id = #{requestId}
  AND tool_call_id = #{toolCallId}
LIMIT 1

SELECT COUNT(1)
FROM ai_agent_tool_output_image_generation
WHERE request_source = #{requestSource}

SELECT id, tool_invocation_id, run_id, request_id, request_source, session_id, tool_call_id, status, error_msg,
       prompt, mode, summary, size, batch_count, source_image_count, mask_image_count, used_fallback, created_at, updated_at
FROM ai_agent_tool_output_image_generation
WHERE request_source = #{requestSource}
ORDER BY created_at DESC, id DESC
LIMIT #{offset}, #{limit}
